import { useState } from 'react';
import styles from './InvestmentForm.module.css';

const InvestmentForm = ({ onAddInvestment }) => {
  const [formData, setFormData] = useState({
    brand: '',
    processor: '',
    generation: '',
    initialCost: '',
    salePrice: '',
  });

  // Opciones de marcas predefinidas
  const brands = [
    'Lenovo',
    'HP',
    'Acer',
    'Fujitsu',
    'Dell',
    'MSI',
    'Asus',
    'Gateway',
    'Lenovo ThinkPad',
  ];

  // Opciones de procesadores (Intel y AMD)
  const processors = [
    'Intel Celeron',
    'Intel Core i3',
    'Intel Core i5',
    'Intel Core i7',
    'Intel Core i9',
    'AMD Ryzen 3',
    'AMD Ryzen 5',
    'AMD Ryzen 7',
    'AMD Ryzen 9',
  ];

  // Opciones de generación (desde la 4ta hasta la 14ta)
  const generations = Array.from({ length: 11 }, (_, i) => i + 4); // Genera números del 4 al 14

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const profit = parseFloat(formData.salePrice) - parseFloat(formData.initialCost);
    onAddInvestment({
      ...formData,
      initialCost: parseFloat(formData.initialCost),
      salePrice: parseFloat(formData.salePrice),
      profit,
    });
    setFormData({
      brand: '',
      processor: '',
      generation: '',
      initialCost: '',
      salePrice: '',
    });
  };

  return (
    <form className={styles.form} onSubmit={handleSubmit}>
      <h2>Registrar Inversión en Laptop</h2>

      {/* Campo de selección para la marca */}
      <select
        name="brand"
        value={formData.brand}
        onChange={handleChange}
        required
      >
        <option value="" disabled>
          Selecciona una marca
        </option>
        {brands.map((brand, index) => (
          <option key={index} value={brand}>
            {brand}
          </option>
        ))}
      </select>

      {/* Campo de selección para el procesador */}
      <select
        name="processor"
        value={formData.processor}
        onChange={handleChange}
        required
      >
        <option value="" disabled>
          Selecciona un procesador
        </option>
        {processors.map((processor, index) => (
          <option key={index} value={processor}>
            {processor}
          </option>
        ))}
      </select>

      {/* Campo de selección para la generación */}
      <select
        name="generation"
        value={formData.generation}
        onChange={handleChange}
        required
      >
        <option value="" disabled>
          Selecciona una generación
        </option>
        {generations.map((generation) => (
          <option key={generation} value={generation}>
            {generation}ª Generación
          </option>
        ))}
      </select>

      <input
        type="number"
        name="initialCost"
        placeholder="Costo Inicial"
        value={formData.initialCost}
        onChange={handleChange}
        required
      />
      <input
        type="number"
        name="salePrice"
        placeholder="Precio de Venta"
        value={formData.salePrice}
        onChange={handleChange}
        required
      />
      <button type="submit">Agregar Inversión</button>
    </form>
  );
};

export default InvestmentForm;
